import pytest

def apply_discount(price: float, code: str) -> float:
    """Apply discount based on code. SAVE10=10%, SAVE20=20%, else no change."""
    if code == "SAVE10":
        return price * 0.9
    elif code == "SAVE20":
        return price * 0.8
    else:
        return price


class TestApplyDiscount:
    def test_save10(self):
        assert apply_discount(100.0, "SAVE10") == pytest.approx(90.0)

    def test_save20(self):
        assert apply_discount(100.0, "SAVE20") == pytest.approx(80.0)

    def test_unknown_code_no_change(self):
        assert apply_discount(50.0, "INVALID") == 50.0

    def test_empty_code_no_change(self):
        assert apply_discount(75.0, "") == 75.0

    def test_zero_price_save10(self):
        assert apply_discount(0.0, "SAVE10") == 0.0

    def test_zero_price_save20(self):
        assert apply_discount(0.0, "SAVE20") == 0.0

    def test_case_sensitive_lowercase(self):
        # Codes are case-sensitive per spec; lowercase should not match
        assert apply_discount(100.0, "save10") == 100.0

    def test_case_sensitive_mixed(self):
        assert apply_discount(100.0, "Save10") == 100.0

    def test_float_precision(self):
        result = apply_discount(19.99, "SAVE10")
        assert result == pytest.approx(17.991)

    def test_negative_price_save10(self):
        # Edge case: negative prices still get discounted proportionally
        assert apply_discount(-100.0, "SAVE10") == pytest.approx(-90.0)

    def test_large_price_save20(self):
        assert apply_discount(1_000_000.0, "SAVE20") == pytest.approx(800_000.0)
